SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(*), 0) AS mortality_rate, AVG(a.los) AS average_length_of_stay, COUNT(DISTINCT CASE WHEN d.icd_code IN ('250.0', '251.0') THEN d.subject_id END) AS diabetes_patients, COUNT(DISTINCT CASE WHEN d.icd_code IN ('250.0', '251.0') THEN d.subject_id END) AS ckd_patients FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 82 AND p.anchor_year_group = 'HF' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2020 AND (i.first_careunit = 'ICU' OR i.first_careunit = 'ICU-1') AND (a.dischtime - a.admittime) BETWEEN 1 AND 7 AND (a.dischtime - a.admittime) NOT BETWEEN 8 AND 14 AND (a.dischtime - a.admittime) NOT BETWEEN 15 AND 21 AND (a.dischtime - a.admittime) NOT BETWEEN 22 AND 28 AND (a.dischtime - a.admittime) NOT BETWEEN 29 AND 35 AND (a.dischtime - a.admittime) NOT BETWEEN 36 AND 42 AND (a.dischtime - a.admittime) NOT BETWEEN 43 AND 49 AND (a.dischtime - a.admittime) NOT BETWEEN 50 AND 56 AND (a.dischtime - a.admittime) NOT BETWEEN 57 AND 63 AND (a.dischtime - a.admittime) NOT BETWEEN 64 AND 70 AND (a.dischtime - a.admittime) NOT BETWEEN 71 AND 77 AND (a.dischtime - a.admittime) NOT BETWEEN 78 AND 84 AND (a.dischtime - a.admittime) NOT BETWEEN 85 AND 91 AND (a.dischtime - a.admittime) NOT BETWEEN 92 AND 98 AND (a.dischtime - a.admittime) NOT BETWEEN 99 AND 105;